cd "$ARCHON_HORIZON_ROOT" && "$HORIZON_BIN" roadmap list --focus AJCR.w4-rep.datum --json 2>/dev/null > /tmp/rm.json; python3 - <<'EOF'
import json
d=json.load(open('/tmp/rm.json'))
items=d['items'] if isinstance(d,dict) else d
want={'AJCR.w4-rep.datum.dat-d.ddr.divrep.u2','AJCR.w4-rep.datum.dat-d.ddr.divrep','AJCR.w4-rep.datum.dat-d.ddr.datum-tail','AJCR.w4-rep.datum.dat-g','AJCR.w4-rep.datum.dat-glue','AJCR.w4-rep.datum.dat-j','AJCR.w4-rep.datum.dat-d.ddq','AJCR.w4-rep.datum.dat-d.ddr.flattening-fallback'}
for it in items:
    if it.get('id') in want or it.get('name') in want:
        print('='*30, it.get('id') or it.get('name'), it.get('status'))
        for k,v in it.items():
            if k in ('id','name','status'): continue
            if not v: continue
            print(f'-- {k}: {v}')
EOF
